-- Lote 08 do catálogo de talentos SRD. Tradução; sem alteração de engine_status.
begin;
update public.srd_feats set nome_pt='Mãos Leves', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Prestidigitação e Usar Cordas.' where id='srd35_feat_deft_hands';
update public.srd_feats set nome_pt='Duro de Matar', descricao_pt='Pré-requisito: Resistência. Benefício: Quando seus pontos de vida são reduzidos a um valor entre –1 e –9, você se estabiliza automaticamente. Não precisa realizar uma jogada percentual para verificar se perde 1 ponto de vida a cada rodada. Quando seus pontos de vida ficam negativos, você pode escolher agir como se estivesse incapacitado, em vez de morrer. Deve tomar essa decisão assim que seus pontos de vida forem reduzidos a um valor negativo, mesmo que não seja seu turno. Se não escolher agir como incapacitado, fica inconsciente imediatamente. Ao usar este talento, você pode realizar uma ação de movimento ou uma ação padrão por turno, mas não ambas, e não pode realizar ações de rodada completa. Você pode realizar uma ação de movimento sem se ferir ainda mais; porém, se realizar uma ação padrão ou outra ação considerada extenuante, sofre 1 ponto de dano após concluí-la. Se chegar a –10 pontos de vida, morre imediatamente. Normal: Sem este talento, um personagem reduzido a um valor entre –1 e –9 pontos de vida fica inconsciente e morrendo.' where id='srd35_feat_diehard';
update public.srd_feats set nome_pt='Diligente', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Avaliação e Decifrar Escrita.' where id='srd35_feat_diligent';
update public.srd_feats set nome_pt='Potencializar Magia', descricao_pt='Benefício: Todos os efeitos variáveis e numéricos de uma magia potencializada são aumentados em 50%. Testes de resistência e jogadas resistidas não são afetados, assim como magias sem variáveis aleatórias. Uma magia potencializada ocupa um espaço de magia dois níveis acima do nível real da magia.' where id='srd35_feat_empower_spell';
update public.srd_feats set nome_pt='Resistência', descricao_pt='Benefício: Você recebe +4 de bônus nos seguintes testes e salvamentos: testes de Natação para resistir a dano não letal; testes de Constituição para continuar correndo, evitar dano não letal de uma marcha forçada, prender a respiração ou evitar dano não letal por fome ou sede; testes de resistência de Fortitude para evitar dano não letal de ambientes quentes ou frios e para resistir a dano por sufocamento. Além disso, você pode dormir usando armadura leve ou média sem ficar fatigado. Normal: Um personagem sem este talento que durma usando armadura média ou pesada fica automaticamente fatigado no dia seguinte. Especial: Um ranger recebe automaticamente Resistência como talento adicional no 3º nível.' where id='srd35_feat_endurance';
commit;